def avaliar_posfixa(tokens):
    pilha = []
    for t in tokens:
        if t in ('+', '-', '*'):
            b = pilha.pop()
            a = pilha.pop()
            pilha.append(a + b if t == '+' else (a - b if t == '-' else a * b))
        else:
            pilha.append(int(t))
